{"code": "import json, os, shutil

ROOT = '/app/config'
BACKUP = '/tmp/hermes/cache/scratch/config_backup'

files = ['/app/config/app.json','/app/config/db.json',
         '/app/config/services/payments.json','/app/config/services/search.json']

def rename_pairs(pairs):
    ks = [k for k, _ in pairs]
    assert len(set(ks)) == len(ks), f'duplicate keys: {ks}'
    return {('max_retries' if k == 'retries' else k): v for k, v in pairs}

def count_key(o, key):
    n = 0
    if isinstance(o, dict):
        for k, v in o.items():
            n += (k == key) + count_key(v, key)
    elif isinstance(o, list):
        for v in o:
            n += count_key(v, key)
    return n

changed = []
for p in files:
    text = open(p, encoding='utf-8').read()
    data = json.loads(text)
    json.loads(text, object_pairs_hook=rename_pairs)  # duplicate-key check
    n = count_key(data, 'retries')
    if n == 0:
        print(f'{p}: no "retries" keys, untouched')
        continue
    nl = '\n' if text.endswith('\n') else ''
    # build formatting candidates: sniffed indent first, then common defaults
    sniffs = []
    for line in text.splitlines()[1:]:
        if line[:1] in (' ', '\t'):
            sniffs.append(line[:len(line) - len(line.lstrip(' \t'))])
            break
    cands = []
    for ind in sniffs + [2, 4, 3, 8, '\t', None]:
        for ea in (True, False):
            if ind is None:
                for seps in ((', ', ': '), (',', ':')):
                    cands.append((ind, seps, ea))
            else:
                for seps in ((',', ': '), (', ', ': ')):
                    cands.append((ind, seps, ea))
    fmt = None
    for ind, seps, ea in cands:
        if json.dumps(data, indent=ind, separators=seps, ensure_ascii=ea) + nl == text:
            fmt = (ind, seps, ea); break
    assert fmt, f'{p}: could not reproduce formatting exactly'
    bp = os.path.join(BACKUP, os.path.relpath(p, ROOT))
    os.makedirs(os.path.dirname(bp), exist_ok=True)
    shutil.copy2(p, bp)
    new_text = json.dumps(json.loads(text, object_pairs_hook=rename_pairs),
                          indent=fmt[0], separators=fmt[1], ensure_ascii=fmt[2]) + nl
    assert count_key(json.loads(new_text), 'retries') == 0
    open(p, 'w', encoding='utf-8').write(new_text)
    changed.append((p, n))
    print(f'{p}: renamed {n} key(s); exact formatting preserved ({fmt})')

print('TOTAL renamed:', sum(n for _, n in changed))
"}

