def scalar(s):
    s = s.strip()
    if s.startswith(("'", '"')) and s.endswith(s[0]) and len(s) >= 2:
        return s[1:-1]
    if s.startswith("{") and s.endswith("}"):
        out = {}
        for part in split_top(s[1:-1]):
            k, v = part.split(":", 1)
            out[scalar(k)] = scalar(v)
        return out
    if s in ("true", "True"): return True
    if s in ("false", "False"): return False
    try: return int(s)
    except ValueError: pass
    try: return float(s)
    except ValueError: pass
    return s

def split_top(s):
    parts, depth, cur = [], 0, ""
    for ch in s:
        if ch in "{[": depth += 1
        elif ch in "}]": depth -= 1
        if ch == "," and depth == 0:
            parts.append(cur); cur = ""
        else:
            cur += ch
    if cur.strip(): parts.append(cur)
    return parts

doc, anchors = {}, {}
