{"content": """"Fallback renderer: replicates tools/render.py exactly, with a minimal YAML
parser (no PyYAML available on this offline box) covering only the constructs
used in config/services.yaml: anchors, merge keys (<<), block mappings and
sequences, flow mappings, quoted/plain scalars, ints, comments.
"""
import json
import re

SRC = "config/services.yaml"
DST = "out/services.json"


# ---------- minimal YAML subset parser ----------

def _strip_comment(line):
    out, q = "", None
    for ch in line:
        if q:
            out += ch
            if ch == q:
                q = None
        elif ch in "\"'":
            q = ch
            out += ch
        elif ch == "#":
            break
        else:
            out += ch
    return out.rstrip()


def _scalar(tok):
    tok = tok.strip()
    if len(tok) >= 2 and tok[0] == tok[-1] and tok[0] in "\"'":
        return tok[1:-1]
    if re.fullmatch(r"-?\d+", tok):
        return int(tok)
    if tok in ("true", "True"):
        return True
    if tok in ("false", "False"):
        return False
    if tok in ("null", "~", ""):
        return None
    return tok


def _flow(tok):
    """Parse a flow mapping like {REGION: us-east, LOG_LEVEL: \"error\"}."""
    tok = tok.strip()
    assert tok.startswith("{") and tok.endswith("}")
    body = tok[1:-1].strip()
    d = {}
    if not body:
        return d
    # split on commas outside quotes
    parts, cur, q = [], "", None
    for ch in body:
        if q:
            cur += ch
            if ch == q:
                q = None
        elif ch in "\"'":
            q = ch
            cur += ch
        elif ch == ",":
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    parts.append(cur)
    for part in parts:
        k, _, v = part.partition(":")
        d[_scalar(k)] = _scalar(v)
    return d


def _parse_block(lines, i, indent):
    """Parse node starting at lines[i] with given indent. Returns (value, next_i)."""
    # sequence?
    if lines[i].lstrip().startswith("- "):
        seq = []
        while i < len(lines):
            stripped = lines[i].strip()
            cur = len(lines[i]) - len(lines[i].lstrip())
            if cur != indent or not stripped.startswith("- "):
                break
            rest = stripped[2:]
            if ":" in _strip_comment(rest) and not rest.startswith("{"):
                # mapping whose first key is on the dash line
                inline_items = []
                k, _, v = rest.partition(":")
                if v.strip():
                    inline_items.append((k.strip(), v.strip()))
                entry, i = _parse_map_body(lines, i + 1, indent + 2, inline_items)
                seq.append(entry)
            else:
                seq.append(_scalar(rest))
                i += 1
        return seq, i
    return _parse_map_body(lines, i, indent, [])


def _parse_map_body(lines, i, indent, pre_items):
    d, merged = {}, {}
    items = list(pre_items)
    while i < len(lines):
        stripped = lines[i].strip()
        cur = len(lines[i]) - len(lines[i].lstrip())
        if cur < indent or stripped.startswith("- "):
            break
        assert cur == indent, f"bad indent at line {i+1}: {lines[i]!r}"
        key, _, rest = stripped.partition(":")
        key, rest = key.strip(), rest.strip()
        if key == "<<":
            assert rest.startswith("*"), "only *anchor merges supported"
            merged.update(anchors[rest[1:]])
            i += 1
        elif rest == "":
            # nested block (or anchor definition line like 'defaults: &defaults')
            anchor = None
            i += 1
            if i < len(lines):
                nxt = lines[i].strip()
                cur_next = len(lines[i]) - len(lines[i].lstrip())
                if cur_next > indent or (cur_next == indent and nxt.startswith("- ")):
                    val, i = _parse_block(lines, i, cur_next)
                    d[key] = val
                    continue
                if nxt.startswith("&"):
                    anchor = nxt[1:].strip()
                    i += 1
            # empty value (or anchor with block following handled above)
            val, i = _parse_block(lines, i, indent) if i < len(lines) and (len(lines[i]) - len(lines[i].lstrip())) == indent and lines[i].strip().startswith("- ") else (None, i)
            if anchor:
                anchors[anchor] = val
            d[key] = val
        elif rest.startswith("&"):
            anchor, rest2 = rest[1:].split(None, 1)
            d[key] = _scalar(rest2) if rest2 else None
            anchors[anchor] = d[key]
            i += 1
        else:
            d[key] = _flow(rest) if rest.startswith("{") else _scalar(rest)
            i += 1
    for k, v in items:
        d[k] = _flow(v) if v.startswith("{") else _scalar(v)
    if merged:
        return {**merged, **d}, i
    return d, i


anchors = {}

raw = open(SRC).read().splitlines()
lines = [_strip_comment(l) for l in raw]
lines = [l for l in lines if l.strip()]
doc, _ = _parse_block(lines, 0, 0)


# ---------- render logic copied verbatim from tools/render.py ----------

def render(doc: dict) -> dict:
    defaults = doc["defaults"]
    out = []
    for svc in doc["services"]:
        if not svc.get("enabled", True):
            continue
        env = {**defaults["env"], **svc.get("env", {})}
        out.append(
            {
                "name": svc["name"],
                "url": f"http://{svc['host']}:{svc['port']}{svc['health_path']}",
                "replicas": svc["replicas"],
                "env": dict(sorted(env.items())),
            }
        )
    return {"services": sorted(out, key=lambda s: s["name"])}


import pathlib
pathlib.Path("out").mkdir(exist_ok=True)
pathlib.Path(DST).write_text(json.dumps(render(doc), indent=2) + "\n")
print("rendered out/services.json")
