print('ptrs', [hex(p) for p in ptrs])

def varint(b, i):
    n = 0
    for k in range(9):
        c = b[i]; i += 1
        if k == 8:
            n = (n << 8) | c; break
        n = (n << 7) | (c & 0x7f)
        if not c & 0x80: break
    return n, i

def stype_len(t):
    if t in (0,8,9,12): return 0
    return {1:1,2:2,3:3,4:4,5:6,6:8,7:8}[t] if t <= 7 else ((t-12)//2 if t%2==0 else (t-13)//2)

rows = []
for p in ptrs:
    plen, i = varint(data, p)
    rowid, i = varint(data, i)
    payload = data[i:i+plen]
    hlen, j = varint(payload, 0)
    types = []
    while j < hlen:
        t, j = varint(payload, j); types.append(t)
    vals, k = [], hlen
    for t in types:
        L = stype_len(t); raw = payload[k:k+L]; k += L
        if t == 0: vals.append(None)
        elif 1 <= t <= 6: vals.append(int.from_bytes(raw,'big',signed=True))
        elif t == 8: vals.append(0)
        elif t == 9: vals.append(1)
        elif t == 7: vals.append(struct.unpack('>d', raw)[0])
        elif t >= 13 and t % 2: vals.append(raw.decode('utf-8'))
        else: vals.append(raw.hex())
    rows.append((rowid, vals))
    print(rowid, vals)

out = [{"word": v[1], "value": v[2]} for _, v in sorted(rows)]
json.dump(out, open('/app/recover.json','w'))
print('wrote', len(out))"}

{"content": "#!/usr/bin/env python3
"""Python re-implementation of program.cbl (BOOKFORUM).

Reads one transaction from src/INPUT.DAT, validates buyer/seller/book,
and if valid: debits buyer, credits seller, transfers book ownership,
and appends to TRANSACTIONS.DAT. Fixed-length records, no line breaks.
"""
import os

DATA = "data"
ACC = os.path.join(DATA, "ACCOUNTS.DAT")
BOOKS = os.path.join(DATA, "BOOKS.DAT")
TRANS = os.path.join(DATA, "TRANSACTIONS.DAT")
INP = os.path.join("src", "INPUT.DAT")

MOD = 10 ** 10  # PIC 9(10) arithmetic truncates to 10 digits


def read_records(path, size):
    if not os.path.exists(path):
        return []
    with open(path, "rb") as f:
        raw = f.read()
    return [raw[i:i + size] for i in range(0, len(raw), size)]


def write_records(path, recs, size):
    with open(path, "wb") as f:
        for r in recs:
            f.write(r.ljust(size, b" ")[:size])


def field(rec, start, end):
    return rec[start:end].decode("latin-1")


def zoned_to_int(b):
    s = b.decode("latin-1")
    return int(s) if s.strip("0123456789") == "" and s else 0


def int_to_zoned(n, width):
    return str(n % MOD).rjust(width, "0").encode()


def main():
    inp = read_records(INP, 22)
    if not inp:
        print("Error: Input file is empty")
        return
    rec = inp[0].ljust(22, b" ")
    buyer = field(rec, 0, 4)
    seller = field(rec, 4, 8)
    book = field(rec, 8, 12)
    amount = zoned_to_int(rec[12:22])

    buyer_found = seller_found = book_found = valid_owner = False

    for a in read_records(ACC, 34):
        if field(a, 0, 4) == buyer:
            buyer_found = True
        if field(a, 0, 4) == seller:
            seller_found = True

    for b in read_records(BOOKS, 28):
        if field(b, 0, 4) == book:
            book_found = True
            if field(b, 24, 28) == seller:
                valid_owner = True

    print(" ")

    if not (buyer_found and seller_found and book_found and valid_owner):
        print("Transaction failed due to validation errors")
        return

    # PROCESS-TRANSACTION
    accs = []
    for a in read_records(ACC, 34):
        bal = zoned_to_int(a[24:34])
        if field(a, 0, 4) == buyer:
            bal -= amount
        if field(a, 0, 4) == seller:
            bal += amount
        # unsigned PIC 9(10) stores truncated result of the arithmetic
        accs.append(a[:24] + int_to_zoned(bal, 10))
    write_records(ACC, accs, 34)

    bks = []
    for b in read_records(BOOKS, 28):
        if field(b, 0, 4) == book:
            b = b[:24] + buyer.encode("latin-1").ljust(4, b" ")
        bks.append(b)
    write_records(BOOKS, bks, 28)

    t = (book.encode("latin-1").ljust(4) + int_to_zoned(amount, 10)
         + seller.encode("latin-1").ljust(4) + buyer.encode("latin-1").ljust(4))
    write_records(TRANS, read_records(TRANS, 22) + [t], 22)

    print("Transaction completed successfully")


if __name__ == "__main__":
    main()
