{"code": "import json, os

reqs = open('/app/requirements.txt').read().splitlines()
advs = json.load(open('/app/security/advisories.json'))
mirror = {}
for line in open('/app/security/index.txt'):
    p = line.split()
    if p: mirror[p[0]] = p[1:]

def vtuple(v): return tuple(int(x) for x in v.split('.'))
def ge(a,b): return vtuple(a) >= vtuple(b)

upgrades = []  # (line_idx, package, from, to, [ids])
for i, line in enumerate(reqs):
    if '==' not in line or line.strip().startswith('#'): continue
    spec = line.split('#')[0].strip()
    name = spec.split('[')[0].split('==')[0].strip()
    ver = spec.split('==')[1].strip()
    hits = [a for a in advs if a['package'] == name and a['id'].startswith('GHSA')]
    affected = []
    for a in hits:
        rng = a['affected']
        v = ver
        ok = True
        # parse simple range like ">=2.0.0,<2.2.2" or "<3.0.3"
        for part in rng.split(','):
            part = part.strip()
            if part.startswith('>='): ok = ok and ge(v, part[2:])
            elif part.startswith('>=') is False and part.startswith('<'): ok = ok and vtuple(v) < vtuple(part[1:])
        if ok: affected.append(a)
    if not affected: continue
    need = max((a['fixed_in'] for a in affected), key=vtuple)
    avail = [v for v in mirror.get(name, []) if ge(v, need)]
    if not avail:
        print(f"NO MIRROR VERSION for {name} (need {need})"); continue
    to = min(avail, key=vtuple)
    upgrades.append((i, name, ver, to, [a['id'] for a in affected]))
    reqs[i] = f"{name}=={to}"

print(json.dumps([{'package':u[1],'from':u[2],'to':u[3],'advisories':u[4]} for u in upgrades], indent=2))
os.makedirs('/app/out', exist_ok=True)
open('/app/requirements.txt','w').write('\n'.join(reqs)+'\n')
json.dump([{'package':u[1],'from':u[2],'to':u[3],'advisories':u[4]} for u in upgrades], open('/app/out/audit.json','w'), indent=2)
"}

