    violations.append({"table": table, "row": row, "column": column, "rule": rule})

DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
def valid_date(s):
    if not DATE_RE.match(s):
        return False
    try:
        datetime.strptime(s, "%Y-%m-%d")
        return True
    except ValueError:
        return False

def is_num(s):
    try:
        float(s)
        return True
    except ValueError:
        return False

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[a-z]{2,}$")

def check_not_null(table, rownum, row, cols):
    for c in cols:
        if row[c].strip() == "":
            add(table, rownum, c, "not_null")

# customers
seen = set()
for i, r in enumerate(customers, 1):
    check_not_null("customers", i, r, ["id", "email", "signup_date", "tier"])
    if r["id"] in seen:
        add("customers", i, "id", "unique")
    seen.add(r["id"])
    if not EMAIL_RE.match(r["email"]):
        add("customers", i, "email", "email")
    if not valid_date(r["signup_date"]):
        add("customers", i, "signup_date", "date")
    if r["tier"] not in ("free", "pro", "enterprise"):
        add("customers", i, "tier", "enum")

# orders
seen = set()
cust_ids = {r["id"] for r in customers}
order_by_id = {}
for i, r in enumerate(orders, 1):
    check_not_null("orders", i, r, ["id", "customer_id", "order_date", "status", "total"])
    if r["id"] in seen:
        add("orders", i, "id", "unique")
    seen.add(r["id"])
    if r["customer_id"] not in cust_ids:
        add("orders", i, "customer_id", "foreign_key")
    if not valid_date(r["order_date"]):
        add("orders", i, "order_date", "date")
    if r["status"] not in ("placed", "paid", "shipped", "cancelled"):
        add("orders", i, "status", "enum")
    if not is_num(r["total"]) or float(r["total"]) < 0:
        add("orders", i, "total", "range")
    else:
        order_by_id[r["id"]] = float(r["total"])

# products
seen = set()
skus = set()
for i, r in enumerate(products, 1):
    check_not_null("products", i, r, ["sku", "name", "price", "category"])
    if r["sku"] in seen:
        add("products", i, "sku", "unique")
    seen.add(r["sku"])
    skus.add(r["sku"])
    if not is_num(r["price"]) or float(r["price"]) <= 0:
        add("products", i, "price", "range")

# order_items
for i, r in enumerate(order_items, 1):
    check_not_null("order_items", i, r, ["order_id", "sku", "qty", "price"])
    if r["order_id"] not in order_by_id and r["order_id"] in {o["id"] for o in orders}:
        pass  # order exists but invalid total: FK still satisfied
    if r["order_id"] not in {o["id"] for o in orders}:
        add("order_items", i, "order_id", "foreign_key")
    if r["sku"] not in skus:
        add("order_items", i, "sku", "foreign_key")
    qty_ok = re.match(r"^\d+$", r["qty"]) and int(r["qty"]) >= 1
    if not qty_ok:
        add("order_items", i, "qty", "range")
    if not is_num(r["price"]) or float(r["price"]) < 0:
        add("order_items", i, "price", "range")

# refunds
seen = set()
for i, r in enumerate(refunds, 1):
    check_not_null("refunds", i, r, ["id", "order_id", "amount", "date"])
    if r["id"] in seen:
        add("refunds", i, "id", "unique")
    seen.add(r["id"])
    if r["order_id"] not in {o["id"] for o in orders}:
        add("refunds", i, "order_id", "foreign_key")
    amt_ok = is_num(r["amount"]) and float(r["amount"]) > 0
    if not amt_ok:
        add("refunds", i, "amount", "range")
    elif r["order_id"] in order_by_id and float(r["amount"]) > order_by_id[r["order_id"]]:
        add("refunds", i, "amount", "refund_le_total")
    if not valid_date(r["date"]):
        add("refunds", i, "date", "date")

# shipments
order_dates = {o["id"]: o["order_date"] for o in orders}
for i, r in enumerate(shipments, 1):
